-- Gerçek checklist maddesi olmayan satırlar: alt bölüm başlıkları (5.2.2, 5.3, 5.9),
-- belirsiz/eylemsiz genel ifade ("TS EN 81-71 standardına göre ek düzenlemeler yapılmalıdır")
-- ve yöntem kodları dipnotu. MAD-1010 emsaliyle pasifleştirildi.
update public.madde_kutuphanesi set aktif = false where madde_id in ('MAD-0849','MAD-0852','MAD-0883','MAD-0887','MAD-0888');

update public.kutuphane_bolum_surumleri set surum = surum + 1, updated_at = now() where bolum = '08 - TS EN 81-71 Tahribata Dayanıklı';

commit;

